document.addEventListener("DOMContentLoaded",()=>{const e={facts:[["State","Rajasthan","Desert National Park is located in Rajasthan's Thar Desert landscape."],["Known for","Thar Desert","The issue asks to showcase the unique desert ecosystem of Desert National Park."],["Flagship species","Great Indian Bustard","The Great Indian Bustard is the key species highlighted for this explorer page."],["Landscape","Sand dunes + scrub","Dunes, rocky patches, grasslands and arid scrub shape the park's biodiversity."],["Climate","Hot arid desert","High heat, low rainfall and strong seasonal variation make survival highly specialised."],["Explorer focus","Wildlife + climate + map","This page teaches dunes, wildlife, flora, climate, gallery and interactive map points."]],wildlife:[["Great Indian Bustard","Flagship species","🪶","A critically important grassland-desert bird and the central conservation symbol of this page."],["Chinkara","Mammal","🦌","A graceful Indian gazelle adapted to arid grasslands and scrub landscapes."],["Desert Fox","Mammal","🦊","A small desert predator adapted to heat, sparse cover and night activity."],["Indian Wolf","Predator","🐺","A dryland predator linked with open scrub, grassland and semi-arid habitats."],["Spiny-tailed Lizard","Reptile","🦎","A desert reptile associated with open sandy and scrubby patches."],["Monitor Lizard","Reptile","🐊","Large reptile species can be part of the arid-zone food web."],["Eagle species","Bird","🦅","Raptors use open desert skies and grasslands for hunting."],["Demoiselle Crane","Bird","🪽","Migratory birds add seasonal richness to desert and wetland-edge habitats."]],dunes:[["Living dune systems","Sand dunes shift with wind, creating habitats for hardy grasses, reptiles and insects."],["Grassland-dune mosaic","Open grasslands around dunes are important for birds such as the Great Indian Bustard."],["Rocky desert patches","Rocky and gravelly areas add microhabitats for reptiles, small mammals and plants."],["Desert silence","Open horizons, wind-shaped sand and sparse vegetation create the park's signature visual identity."]],flora:[["Khejri","Hardy desert trees provide shade, soil support and habitat value in arid regions."],["Sewan grass","Native grasses help stabilise soil and support dryland wildlife."],["Acacia scrub","Thorny shrubs and trees survive low rainfall and provide cover for birds and mammals."],["Desert herbs","Short-lived herbs may appear after rain, showing how quickly desert life responds to moisture."]],climate:[["High heat","Summer temperatures can be extreme, so desert wildlife often avoids peak daytime heat."],["Low rainfall","Sparse rainfall means plants and animals must conserve water and use seasonal opportunities."],["Large day-night variation","Deserts often shift from harsh daytime heat to cooler nights, shaping animal activity."],["Monsoon pulse","Even limited rainfall can trigger plant growth, insects and wildlife movement."]],points:[["jaisalmer","Jaisalmer desert gateway",42,58,"Visitor context","Represents the wider desert gateway for understanding the Thar landscape."],["dunes","Sand dune belt",58,45,"Dune ecosystem","Wind-shaped dunes, scrub and grass patches define the desert visual story."],["bustard","Great Indian Bustard habitat",48,38,"Flagship habitat","Open grassland-desert mosaics are important for the Great Indian Bustard."],["scrub","Arid scrub zone",34,48,"Flora zone","Thorn scrub, grasses and hardy trees support desert wildlife."],["raptor","Open sky raptor zone",70,55,"Bird zone","Open desert skies support raptors and seasonal bird movement."],["water","Seasonal water point",60,70,"Climate adaptation","Rare water and monsoon pulses influence wildlife activity and plant growth."]],gallery:[["Thar Desert horizon","../../assets/travel_hidden.png","Open desert horizons and sparse vegetation define the park's landscape."],["Sand dunes","../../assets/travel_mountains.png","Dunes and dry ridges create a dramatic desert explorer experience."],["Bustard grassland","../../assets/hero_banner.png","Visual placeholder for Great Indian Bustard grassland-desert habitat."],["Desert sky","../../assets/travel_islands.png","Clear skies, raptors and seasonal birds add life to the arid landscape."]],interesting:[["A desert national park","The issue focuses on a rare protected-area theme: desert ecology instead of forests or mountains."],["Bustard conservation","The Great Indian Bustard makes the page conservation-focused and educationally important."],["Survival adaptations","Plants and animals survive through water conservation, heat avoidance and seasonal timing."],["Climate classroom","The park helps explain how heat, low rainfall, dunes, grasses and wildlife interact."]]},a=e=>String(e).replaceAll("&","&amp;").replaceAll("<","&lt;").replaceAll(">","&gt;").replaceAll('"',"&quot;").replaceAll("'","&#039;"),s=e=>document.getElementById(e);function t(e,s,t){return`<article class="${s}"><span>0${t+1}</span><h3>${a(e[0])}</h3><p>${a(e[1])}</p></article>`}function r(t="All"){const r="All"===t?e.wildlife:e.wildlife.filter(e=>e[1]===t);s("wildlife-grid").innerHTML=r.map(e=>`<article class="wildlife-card"><div class="wildlife-emoji" aria-hidden="true">${a(e[2])}</div><span>${a(e[1])}</span><strong>${a(e[0])}</strong><p>${a(e[3])}</p></article>`).join("")}function n(t){const r=e.points.find(e=>e[0]===t)||e.points[0];document.querySelectorAll(".map-pin").forEach(e=>e.classList.toggle("active",e.dataset.point===r[0])),s("map-info").innerHTML=`<span>${a(r[4])}</span><h3>${a(r[1])}</h3><p>${a(r[5])}</p>`}s("facts-grid").innerHTML=e.facts.map(e=>`<article class="fact-card"><span>${a(e[0])}</span><strong>${a(e[1])}</strong><p>${a(e[2])}</p></article>`).join(""),s("dunes-grid").innerHTML=e.dunes.map((e,a)=>t(e,"dune-card",a)).join(""),s("flora-grid").innerHTML=e.flora.map((e,a)=>t(e,"flora-card",a)).join(""),s("climate-grid").innerHTML=e.climate.map((e,a)=>t(e,"climate-card",a)).join(""),s("interesting-grid").innerHTML=e.interesting.map((e,a)=>t(e,"interesting-card",a)).join(""),s("map-pins").innerHTML=e.points.map((e,s)=>`<button class="map-pin" type="button" data-point="${a(e[0])}" style="left:${e[2]}%;top:${e[3]}%" aria-label="${a(e[1])}">${s+1}</button>`).join(""),document.querySelectorAll(".map-pin").forEach(e=>e.addEventListener("click",()=>n(e.dataset.point))),document.querySelectorAll(".filter-btn").forEach(e=>e.addEventListener("click",()=>{document.querySelectorAll(".filter-btn").forEach(e=>e.classList.remove("active")),e.classList.add("active"),r(e.dataset.filter)})),s("gallery-grid").innerHTML=e.gallery.map(e=>`<article class="gallery-card"><img src="${a(e[1])}" alt="${a(e[0])}" onerror="this.src='../../assets/hero_banner.png'"><div><h3>${a(e[0])}</h3><p>${a(e[2])}</p></div></article>`).join(""),r(),n(e.points[0][0]),window.DesertNationalParkExplorer={facts:()=>[...e.facts],wildlife:()=>[...e.wildlife],mapPoints:()=>[...e.points]}});